-- Run after arthub.sql. Adds a fuller ArtHub catalogue without duplicating category names.

SELECT s.id, c.id, 'Botanical Watercolour Set', 'A joyful set of artist watercolours for everyday painting.', 1495
FROM sellers s JOIN categories c ON c.name='Paints' WHERE s.is_approved=TRUE AND NOT EXISTS (SELECT 1 FROM products WHERE title='Botanical Watercolour Set');
SELECT s.id, c.id, 'The Everyday Sketchbook', 'Lay-flat sketchbook with warm white, 120 gsm paper.', 780
FROM sellers s JOIN categories c ON c.name='Paper & Journals' WHERE s.is_approved=TRUE AND NOT EXISTS (SELECT 1 FROM products WHERE title='The Everyday Sketchbook');
SELECT s.id, c.id, 'Soft Pastels — Garden', 'A curated garden-toned set of velvety soft pastels.', 1890
FROM sellers s JOIN categories c ON c.name='Drawing' WHERE s.is_approved=TRUE AND NOT EXISTS (SELECT 1 FROM products WHERE title='Soft Pastels — Garden');

-- Oil colour, varnish, brush, canvas and drawing ranges

SELECT p.id, CONCAT('AH-', p.id), 25 FROM products p WHERE NOT EXISTS (SELECT 1 FROM inventory i WHERE i.product_id=p.id);

SELECT p.id, 'https://images.unsplash.com/photo-1513364776144-60967b0f800f?auto=format&fit=crop&w=900&q=85', TRUE FROM products p WHERE p.title='Botanical Watercolour Set' AND NOT EXISTS (SELECT 1 FROM product_images WHERE product_id=p.id);
SELECT p.id, 'https://images.unsplash.com/photo-1455390582262-044cdead277a?auto=format&fit=crop&w=900&q=85', TRUE FROM products p WHERE p.title='The Everyday Sketchbook' AND NOT EXISTS (SELECT 1 FROM product_images WHERE product_id=p.id);
SELECT p.id, 'https://images.unsplash.com/photo-1531058020387-3be344556be6?auto=format&fit=crop&w=900&q=85', TRUE FROM products p WHERE p.title='Soft Pastels — Garden' AND NOT EXISTS (SELECT 1 FROM product_images WHERE product_id=p.id);
